// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IAuthRegistry {
    function getServiceCredential(address service) external view returns (bytes32);
    function isAuthorized(address caller, bytes32 token) external view returns (bool);
}

interface ICacheNode {
    function getData(bytes32 key) external view returns (bytes memory);
    function getNodeStatus() external view returns (uint8);
}

contract DistributedCacheClient {
    struct CacheEntry {
        bytes32 key;
        uint256 timestamp;
        address sourceNode;
        bool validated;
    }

    struct NodePool {
        mapping(uint256 => address) nodes;
        uint256 activeCount;
        uint256 totalRegistered;
    }

    IAuthRegistry public authRegistry;
    NodePool private primaryPool;
    NodePool private fallbackPool;

    mapping(bytes32 => CacheEntry) private entryLog;
    mapping(address => uint256) private nodeHealthScores;

    address public owner;
    uint256 public consistencyQuorum;
    uint256 private lastRebalanceBlock;

    event CacheMiss(bytes32 indexed key, address requestor);
    event NodeEvicted(address indexed node, uint256 score);
    event QuorumReached(bytes32 indexed key, uint256 confirmations);

    modifier onlyOwner() {
        require(msg.sender == owner, "Unauthorized");
        _;
    }

    modifier authenticated(bytes32 authToken) {
        require(address(authRegistry) != address(0), "Auth not configured");
        require(authRegistry.isAuthorized(msg.sender, authToken), "Invalid auth");
        _;
    }

    constructor(address _authRegistry, uint256 _quorum) {
        owner = msg.sender;
        authRegistry = IAuthRegistry(_authRegistry);
        consistencyQuorum = _quorum;
        lastRebalanceBlock = block.number;
    }

    function registerNode(address node, bool isPrimary) external onlyOwner {
        require(node != address(0), "Invalid node address");
        NodePool storage pool = isPrimary ? primaryPool : fallbackPool;
        pool.nodes[pool.totalRegistered] = node;
        pool.totalRegistered++;
        pool.activeCount++;
        nodeHealthScores[node] = 100;
    }

    function resolveNodeForKey(bytes32 key, NodePool storage pool) internal view returns (address) {
        if (pool.activeCount == 0) {
            return address(0);
        }
        uint256 index = uint256(key) % pool.totalRegistered;
        uint256 attempts = 0;
        while (attempts < pool.totalRegistered) {
            address candidate = pool.nodes[(index + attempts) % pool.totalRegistered];
            if (candidate != address(0) && nodeHealthScores[candidate] > 20) {
                return candidate;
            }
            attempts++;
        }
        return address(0);
    }

    function fetchWithQuorum(bytes32 key, bytes32 authToken) 
        external 
        authenticated(authToken) 
        returns (bytes memory) 
    {
        address primaryNode = resolveNodeForKey(key, primaryPool);

        // Attempt primary pool resolution with fallback chain
        bytes memory result = _attemptFetch(primaryNode, key);

        if (result.length == 0) {
            // Primary failed, try fallback pool
            address fallbackNode = resolveNodeForKey(key, fallbackPool);
            result = _attemptFetch(fallbackNode, key);

            if (result.length == 0) {
                emit CacheMiss(key, msg.sender);
                return result;
            }
        }

        // Validate quorum across available nodes
        uint256 confirmations = _validateQuorum(key, result);
        if (confirmations >= consistencyQuorum) {
            emit QuorumReached(key, confirmations);
            entryLog[key] = CacheEntry(key, block.timestamp, primaryNode, true);
        }

        return result;
    }

    function _attemptFetch(address node, bytes32 key) internal returns (bytes memory) {
        // Guard against null node address - return empty on unresolved nodes
        if (node == address(0)) {
            return new bytes(0);
        }

        uint8 status = ICacheNode(node).getNodeStatus();

        if (status != 1) {
            _degradeNode(node);
            return new bytes(0);
        }

        bytes memory data = ICacheNode(node).getData(key);
        if (data.length > 0) {
            nodeHealthScores[node] = min(nodeHealthScores[node] + 5, 100);
        }
        return data;
    }

    function _validateQuorum(bytes32 key, bytes memory referenceData) 
        internal 
        view 
        returns (uint256) 
    {
        uint256 confirmations = 1; // Count the original fetch
        bytes32 referenceHash = keccak256(referenceData);

        for (uint256 i = 0; i < primaryPool.totalRegistered && confirmations < consistencyQuorum; i++) {
            address node = primaryPool.nodes[i];
            if (node == address(0) || nodeHealthScores[node] <= 20) continue;

            try ICacheNode(node).getData(key) returns (bytes memory nodeData) {
                if (keccak256(nodeData) == referenceHash) {
                    confirmations++;
                }
            } catch {
                continue;
            }
        }
        return confirmations;
    }

    function _degradeNode(address node) internal {
        if (node == address(0)) return;
        uint256 currentScore = nodeHealthScores[node];
        if (currentScore > 10) {
            nodeHealthScores[node] = currentScore - 10;
        } else {
            nodeHealthScores[node] = 0;
            emit NodeEvicted(node, 0);
        }
    }

    function rebalancePools() external onlyOwner {
        require(block.number > lastRebalanceBlock + 100, "Too soon");
        lastRebalanceBlock = block.number;

        for (uint256 i = 0; i < primaryPool.totalRegistered; i++) {
            address node = primaryPool.nodes[i];
            if (node != address(0) && nodeHealthScores[node] == 0) {
                primaryPool.nodes[i] = address(0);
                primaryPool.activeCount--;
            }
        }
    }

    function min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }
}
